def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_ops, opp_ops = list(zip(*history))
    opp_c = opp_ops.count('C')
    opp_d = n - opp_c
    my_c = my_ops.count('C')
    my_d = n - my_c
    my_last, opp_last = history[-1]
    rem = 100 - n

    opp_d5 = opp_ops[-5:].count('D')
    opp_d10 = opp_ops[-10:].count('D')

    punish = 0
    nonpunish = 0
    recent_punish = 0
    recent_start = max(1, n - 6)
    for i, (prev_my, cur_opp) in enumerate(zip(my_ops[:-1], opp_ops[1:]), 1):
        if prev_my == 'D':
            if cur_opp == 'D':
                punish += 1
                if i >= recent_start:
                    recent_punish += 1
            else:
                nonpunish += 1

    opp_rate = (opp_c + 1.0) / (n + 2.0)

    if opp_d == 0:
        if my_d == 0:
            if n >= 85 or (n >= 8 and rng.random() < 0.20):
                return 'D'
            return 'C'
        if nonpunish > 0:
            return 'D'
        return 'C'

    if (
        opp_last == 'C'
        and nonpunish >= 2
        and nonpunish > punish
        and recent_punish == 0
        and opp_rate >= 0.70
        and opp_d10 <= 1
    ):
        return 'D'

    if opp_rate <= 0.35 or opp_d10 >= 4 or opp_d5 >= 3:
        return 'D'

    if (
        rem <= 2
        and opp_last == 'C'
        and nonpunish > punish
        and recent_punish == 0
        and opp_rate >= 0.65
        and opp_d10 <= 2
    ):
        return 'D'

    if opp_last == 'D':
        if n >= 2 and history[-2][0] == 'D' and my_last == 'C':
            if opp_d <= 2 or opp_rate >= 0.60:
                return 'C'
        if opp_d5 <= 1 and opp_rate >= 0.72:
            return 'C'
        if opp_d10 <= 2 and opp_rate >= 0.78:
            return 'C'
        return 'D'

    if my_last == 'D':
        return 'C'

    if opp_rate >= 0.75 and n >= 25 and rem > 2 and rng.random() < 0.015:
        return 'D'

    return 'C'
